  [Services]
}

package "JIR.WebAPI" {
  [Controllers]
  [Middleware]
}

package "JIR.Application" {
  [Commands]
  [Queries]
  [Handlers]
  [DTOs]
}

package "JIR.Infrastructure" {
  [Repositories]
  [DbContext]
  [Services]
}

package "JIR.Domain" {
  [Entities]
  [ValueObjects]
  [Interfaces]
}

package "PostgreSQL" {
  [Database]
